  1→// Package cursor implements the Agent interface for Cursor.
  2→package cursor
  3→
  4→import (
  5→	"context"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"regexp"
 11→	"time"
 12→
 13→	"github.com/entireio/cli/cmd/entire/cli/agent"
 14→	"github.com/entireio/cli/cmd/entire/cli/paths"
 15→)
 16→
 17→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 18→func init() {
 19→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 20→}
 21→
 22→// CursorAgent implements the Agent interface for Cursor IDE.
 23→//
 24→//nolint:revive // CursorAgent is clearer than Agent in this context
 25→type CursorAgent struct{}
 26→
 27→// NewCursorAgent creates a new Cursor agent instance.
 28→func NewCursorAgent() agent.Agent {
 29→	return &CursorAgent{}
 30→}
 31→
 32→// Name returns the agent registry key.
 33→func (c *CursorAgent) Name() agent.AgentName {
 34→	return agent.AgentNameCursor
 35→}
 36→
 37→// Type returns the agent type identifier.
 38→func (c *CursorAgent) Type() agent.AgentType {
 39→	return agent.AgentTypeCursor
 40→}
 41→
 42→// Description returns a human-readable description.
 43→func (c *CursorAgent) Description() string {
 44→	return "Cursor - AI-powered code editor"
 45→}
 46→
 47→func (c *CursorAgent) IsPreview() bool { return true }
 48→
 49→// DetectPresence checks if Cursor is configured in the repository.
 50→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 51→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 52→	if err != nil {
 53→		worktreeRoot = "."
 54→	}
 55→
 56→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 57→	if _, err := os.Stat(cursorDir); err == nil {
 58→		return true, nil
 59→	}
 60→	return false, nil
 61→}
 62→
 63→// GetSessionID extracts the session ID from hook input.
 64→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 65→	return input.SessionID
 66→}
 67→
 68→// ResolveSessionFile returns the path to a Cursor session file.
 69→// Cursor uses JSONL format like Claude Code.
 70→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 71→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 72→}
 73→
 74→// ProtectedDirs returns directories that Cursor uses for config/state.
 75→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 76→
 77→// GetSessionDir returns the directory where Cursor stores session transcripts.
 78→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 79→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 80→		return override, nil
 81→	}
 82→
 83→	homeDir, err := os.UserHomeDir()
 84→	if err != nil {
 85→		return "", fmt.Errorf("failed to get home directory: %w", err)
 86→	}
 87→
 88→	projectDir := sanitizePathForCursor(repoPath)
 89→	return filepath.Join(homeDir, ".cursor", "projects", projectDir), nil
 90→}
 91→
 92→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
 93→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
 94→// contain tool_use blocks. File detection relies on git status instead.
 95→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 96→	if input.SessionRef == "" {
 97→		return nil, errors.New("session reference (transcript path) is required")
 98→	}
 99→
100→	data, err := os.ReadFile(input.SessionRef)
101→	if err != nil {
102→		return nil, fmt.Errorf("failed to read transcript: %w", err)
103→	}
104→
105→	return &agent.AgentSession{
106→		SessionID:  input.SessionID,
107→		AgentName:  c.Name(),
108→		SessionRef: input.SessionRef,
109→		StartTime:  time.Now(),
110→		NativeData: data,
111→	}, nil
112→}
113→
114→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
115→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
116→	if session == nil {
117→		return errors.New("session is nil")
118→	}
119→
120→	if session.AgentName != "" && session.AgentName != c.Name() {
121→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
122→	}
123→
124→	if session.SessionRef == "" {
125→		return errors.New("session reference (transcript path) is required")
126→	}
127→
128→	if len(session.NativeData) == 0 {
129→		return errors.New("session has no native data to write")
130→	}
131→
132→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
133→		return fmt.Errorf("failed to write transcript: %w", err)
134→	}
135→
136→	return nil
137→}
138→
139→// FormatResumeCommand returns an instruction to resume a Cursor session.
140→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
141→func (c *CursorAgent) FormatResumeCommand(_ string) string {
142→	return "Open this project in Cursor IDE to continue the session."
143→}
144→
145→// sanitizePathForCursor converts a path to Cursor's project directory format.
146→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
147→
148→func sanitizePathForCursor(path string) string {
149→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
150→}
151→
152→// ChunkTranscript splits a JSONL transcript at line boundaries.
153→func (c *CursorAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
154→	chunks, err := agent.ChunkJSONL(content, maxSize)
155→	if err != nil {
156→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
157→	}
158→	return chunks, nil
159→}
160→
161→// ReassembleTranscript concatenates JSONL chunks with newlines.
162→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
163→	return agent.ReassembleJSONL(chunks), nil
164→}
