 51→func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
 52→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
 53→	if err != nil {
 54→		return nil, err
 55→	}
 56→	return &agent.Event{
 57→		Type:       agent.SessionStart,
 58→		SessionID:  raw.ConversationID,
 59→		SessionRef: raw.TranscriptPath,
 60→		Timestamp:  time.Now(),
 61→	}, nil
 62→}
 63→
 64→func (c *CursorAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
 65→	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
 66→	if err != nil {
 67→		return nil, err
 68→	}
 69→	return &agent.Event{
 70→		Type:       agent.TurnStart,
 71→		SessionID:  raw.ConversationID,
 72→		SessionRef: raw.TranscriptPath,
 73→		Prompt:     raw.Prompt,
 74→		Timestamp:  time.Now(),
 75→	}, nil
 76→}
 77→
 78→func (c *CursorAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
 79→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
 80→	if err != nil {
 81→		return nil, err
 82→	}
 83→	return &agent.Event{
 84→		Type:       agent.TurnEnd,
 85→		SessionID:  raw.ConversationID,
 86→		SessionRef: raw.TranscriptPath,
 87→		Timestamp:  time.Now(),
 88→	}, nil
 89→}
 90→
 91→func (c *CursorAgent) parseSessionEnd(stdin io.Reader) (*agent.Event, error) {
 92→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
 93→	if err != nil {
 94→		return nil, err
 95→	}
 96→	return &agent.Event{
