116→
117→func (c *CursorAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
118→	raw, err := agent.ReadAndParseHookInput[subagentStartHookInputRaw](stdin)
119→	if err != nil {
120→		return nil, err
121→	}
122→	if raw.Task == "" {
123→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
124→	}
125→	return &agent.Event{
126→		Type:            agent.SubagentStart,
127→		SessionID:       raw.ConversationID,
128→		SessionRef:      raw.TranscriptPath,
129→		SubagentID:      raw.SubagentID,
130→		ToolUseID:       raw.SubagentID,
131→		SubagentType:    raw.SubagentType,
132→		TaskDescription: raw.Task,
133→		Timestamp:       time.Now(),
134→	}, nil
135→}
136→
137→func (c *CursorAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
138→	raw, err := agent.ReadAndParseHookInput[subagentStopHookInputRaw](stdin)
139→	if err != nil {
140→		return nil, err
141→	}
142→	if raw.Task == "" {
143→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
144→	}
145→	event := &agent.Event{
146→		Type:            agent.SubagentEnd,
147→		SessionID:       raw.ConversationID,
148→		SessionRef:      raw.TranscriptPath,
149→		ToolUseID:       raw.SubagentID,
150→		SubagentType:    raw.SubagentType,
151→		TaskDescription: raw.Task,
152→		Timestamp:       time.Now(),
153→		SubagentID:      raw.SubagentID,
154→	}
155→	return event, nil
156→}
