 13→func TestParseHookEvent_SessionStart(t *testing.T) {
 14→	t.Parallel()
 15→
 16→	ag := &CursorAgent{}
 17→	input := `{"conversation_id": "test-session-123", "transcript_path": "/tmp/transcript.jsonl"}`
 18→
 19→	event, err := ag.ParseHookEvent(context.Background(), HookNameSessionStart, strings.NewReader(input))
 20→
 21→	if err != nil {
 22→		t.Fatalf("unexpected error: %v", err)
 23→	}
 24→	if event == nil {
 25→		t.Fatal("expected event, got nil")
 26→	}
 27→	if event.Type != agent.SessionStart {
 28→		t.Errorf("expected event type %v, got %v", agent.SessionStart, event.Type)
 29→	}
 30→	if event.SessionID != "test-session-123" {
 31→		t.Errorf("expected session_id 'test-session-123', got %q", event.SessionID)
 32→	}
 33→	if event.SessionRef != "/tmp/transcript.jsonl" {
 34→		t.Errorf("expected session_ref '/tmp/transcript.jsonl', got %q", event.SessionRef)
 35→	}
 36→	if event.Timestamp.IsZero() {
 37→		t.Error("expected non-zero timestamp")
 38→	}
 39→}
