280→func TestParseHookEvent_AllHookTypes(t *testing.T) {
281→	t.Parallel()
282→
283→	testCases := []struct {
284→		hookName      string
285→		expectedType  agent.EventType
286→		expectNil     bool
287→		inputTemplate string
288→	}{
289→		{
290→			hookName:      HookNameSessionStart,
291→			expectedType:  agent.SessionStart,
292→			inputTemplate: `{"session_id": "s1", "transcript_path": "/t"}`,
293→		},
